#!/data/data/com.termux/files/usr/bin/bash
set -Eeuo pipefail
cd "$HOME/companyos"
source "$HOME/.companyos_launch_env" 2>/dev/null || true

STAMP="$(date +%Y%m%d_%H%M%S)"
BK="$HOME/companyos/.companyos_backups/capability_feedback_v7_$STAMP"
mkdir -p "$BK"
cp -a companyos/runtime/capability_expansion.py "$BK/" 2>/dev/null || true
cp -a companyos/runtime/service_supervisor.py "$BK/" 2>/dev/null || true

echo "" | base64 -d > companyos/runtime/capability_feedback.py
echo "" | base64 -d > scripts/companyos_feedbackctl
chmod +x scripts/companyos_feedbackctl
echo "" | base64 -d > tests/test_capability_feedback_v7.py

echo "" | base64 -d > "$PREFIX/tmp/companyos_feedback_patch_engine.py"
python "$PREFIX/tmp/companyos_feedback_patch_engine.py"
rm -f "$PREFIX/tmp/companyos_feedback_patch_engine.py"

echo "" | base64 -d > "$PREFIX/tmp/companyos_feedback_patch_supervisor.py"
python "$PREFIX/tmp/companyos_feedback_patch_supervisor.py"
rm -f "$PREFIX/tmp/companyos_feedback_patch_supervisor.py"

echo "[1/7] Compile"
python -m py_compile companyos/runtime/capability_feedback.py companyos/runtime/capability_expansion.py companyos/runtime/service_supervisor.py tests/test_capability_feedback_v7.py

echo "[2/7] Unit tests"
python -m unittest tests.test_capability_feedback_v7 -v

echo "[3/7] First feedback cycle"
scripts/companyos_feedbackctl once | tee .companyos_runtime/capability_feedback_first_cycle.json

echo "[4/7] Expansion compatibility cycle"
scripts/companyos_expandctl once | tee .companyos_runtime/capability_expansion_after_feedback_v7.json || true

echo "[5/7] Commit/push"
git add companyos/runtime/capability_feedback.py companyos/runtime/capability_expansion.py companyos/runtime/service_supervisor.py scripts/companyos_feedbackctl tests/test_capability_feedback_v7.py
git diff --cached --quiet || git commit -m "Add continuous capability feedback and lifecycle management"
BRANCH="$(git branch --show-current)"
[ -n "$BRANCH" ] && git push origin "$BRANCH" || true

echo "[6/7] Restart"
scripts/companyosctl restart || true
sleep 8

echo "[7/7] Verify"
echo "===== FEEDBACK STATUS ====="
scripts/companyos_feedbackctl status || true
echo "===== EXPANSION INVENTORY ====="
scripts/companyos_expandctl inventory || true
echo "===== SERVICES ====="
scripts/companyosctl status || true

echo "BACKUP=$BK"
echo "COMPANYOS_CAPABILITY_FEEDBACK_LOOP_V7=PASS"
